import"./chunk-2NFLSA4Y.js";var t={capacitor:{theory:{concept:"[[A capacitor is a device made of two conductors (plates) separated by an insulator (a dielectric); it stores electric charge and energy.]] Connected to a voltage source, the plates receive equal and opposite charges. The capacitance C = Q/V tells how much charge is stored per volt; for a flat capacitor it grows with the plate area and with the dielectric, and falls as the gap grows: C = \u03B5\u2080\u03B5\u1D63A/d. Through a resistor a capacitor charges and discharges gradually, with the time constant \u03C4 = RC."},section:{geometry:{title:"What sets capacitance?",text:"[[Larger overlapping area gives greater capacitance; a smaller gap also increases it.]] Capacitance depends on geometry and dielectric, not on the selected voltage. The square plates have equal area and remain parallel."},voltage:{title:"Charge and polarity",text:"Q = CV is the signed charge on the left plate; the right plate carries \u2212Q. A negative source voltage swaps the signs and field direction. The capacitor as a whole stays neutral. Charges move through the external circuit, not through the insulating gap."},dielectric:{title:"A dielectric between the plates",text:"The ideal dielectric completely fills the gap. Increasing its relative permittivity \u03B5\u1D63 increases capacitance. At the same final voltage, more free charge and energy are stored; E = V/d is unchanged. This experiment restarts when the dielectric changes, so it does not show inserting material into an already isolated capacitor."},rc:{title:"Charging takes time",text:"The resistor limits current. Charging starts at zero voltage; discharge starts at the selected initial voltage with the source disconnected. After one time constant \u03C4 = RC, charging reaches about 63% of its final voltage, or discharge leaves about 37%. The run stops at 8\u03C4 with a small residual, not exactly full or empty."},energy:{title:"Where the energy goes",text:"[[Stored field energy is \xBDCV\xB2, so doubling voltage quadruples energy.]] During charging, the source supplies energy to both the capacitor and resistor. At full charge, half the source work is stored and half becomes heat. During discharge, stored energy becomes heat in the resistor."}},param:{area:"Overlapping plate area",gap:"Plate separation",voltage:"Source / initial voltage",dielectric:"Relative permittivity \u03B5\u1D63",process:"Charge or discharge",resistance:"Series resistance",timeStep:"Time step"},hint:{area:"Area of one overlapping plate, not the sum of both plates.",gap:"A smaller separation raises capacitance. The drawn gap is enlarged so it remains visible.",voltage:"Charging: source voltage. Discharge: initial capacitor voltage. A negative value reverses polarity.",dielectric:"1 is vacuum; higher values describe an ideal homogeneous dielectric, not a particular real material.",process:"Changing the process restarts: charge begins empty; discharge begins charged to the selected voltage.",resistance:"Very high resistance makes the small-capacitance charging times visible. 1 G\u03A9 = 10\u2079 \u03A9. It changes time, not capacitance."},preset:{small:"Small \xB7 50 cm\xB2",large:"Large \xB7 500 cm\xB2",vacuum:"Vacuum \xB7 \u03B5\u1D63 = 1",ideal:"Ideal dielectric \xB7 \u03B5\u1D63 = 5",charge:"Charge from the source",discharge:"Discharge through the resistor"},measure:{capacitance:"Capacitance",voltage:"Capacitor voltage now",charge:"Left-plate charge (right plate: \u2212Q)",energy:"Stored energy",field:"Signed field (positive: left \u2192 right)",current:"Circuit current (positive: into left plate)",tau:"RC time constant",heat:"Heat produced in resistor",work:"Work supplied by the source"},graph:{charge:"Plate charge over time",energy:"Stored energy and resistor heat"},view:{left:"Left: {value}",right:"Right: {value}",source:"Source \xB7 {value}",discharge:"Source disconnected \xB7 discharge",field:"Field: {value}",status:"Capacitor: {value}",geometry:"A = {area} \xB7 d = {gap} \xB7 \u03B5\u1D63 = {dielectric} \xB7 gap exaggerated",fieldOption:"Electric-field arrows",charges:"Plate charge symbols",current:"Conventional-current markers",dielectric:"Dielectric layer"},formula:{charge:"Charge on one plate",capacitance:"Ideal parallel-plate capacitance",energy:"Stored field energy",field:"Uniform field and RC time constant",rc:"Exact RC charging and discharging"},variable:{epsilon:"Vacuum permittivity: \u03B5\u2080 \u2248 8.854 \xD7 10\u207B\xB9\xB2 F/m"},assumption:{plates:"Perfectly conducting square parallel plates; separation is small compared with width. Fringing fields are ignored.",dielectric:"A homogeneous, lossless, linear dielectric fully fills the gap; leakage, breakdown and dielectric heating are omitted.",circuit:"An ideal voltage source and resistor; wires have no resistance and inductance is ignored. High resistance is used to obtain visible charging times.",initial:"Every setup change restarts. Charging starts at V = 0; discharge starts at the selected voltage with the source disconnected. The run ends at 8RC.",drawing:"The gap is exaggerated relative to plate size. Plate thickness, circuit, arrows and charge symbols are schematic, not to scale. Readings and time retain physical units.",symbols:"The +/\u2212 symbols represent groups of free charge, not individual particles. Moving circuit markers show conventional current schematically, not electron drift speed. No charge crosses the dielectric."},challenge:{capacity:{title:"At least 500 pF",description:"Build a capacitor with capacitance of at least 500 pF.",hint:"Increase plate area or reduce the separation."},charge:{title:"Store 10 nC",description:"Reach a charge magnitude of at least 10 nC on each plate.",hint:"Increase capacitance or voltage and let it charge."},field:{title:"A stronger field",description:"Reach a field magnitude of at least 20,000 N/C.",hint:"Increase voltage or reduce the gap; allow charging."},dielectric:{title:"Five times the capacitance",description:"Make capacitance at least five times its vacuum value for the same geometry.",hint:"Use a dielectric with greater relative permittivity."},discharge:{title:"Release the stored energy",description:"Discharge a nonzero-energy capacitor until no more than 1% of its initial energy remains.",hint:"Select discharge and let the resistor remove the energy."}}}},i={sim:t};export{i as default,t as sim};
